Translate("frFR", "burning-steppes", {
	title = "Steppes ardentes",
	aliases = { "les Steppes" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Steppes ardentes sont un pays de cendre. Entre {link:redridge-mountains}les Carmines{/link} au sud et la masse fumante du {link:blackrock-mountain}Mont Blackrock{/link} au nord-ouest, la terre s'étend noire et brisée, veinée de rivières de pierre en fusion. Rien de vert n'y pousse longtemps. L'air a un goût de cendre, le ciel rougeoie la nuit, et le sol lui-même est chaud sous les pieds. Pourtant, les Steppes ne sont pas un désert vide. Elles sont la seule route terrestre entre le {link:kingdom-of-stormwind}royaume de Stormwind{/link} et les terres naines de Khaz Modan, au-delà de la montagne, et chaque puissance qui convoite cette route est venue en tenir un morceau.]=],
		},
		{
			title = "Origines",
			text = [=[Les Steppes n'ont pas toujours été un désert. Les érudits de {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} disent que la terre formait jadis l'extrémité nord de la chaîne des {link:redridge-mountains}Carmines{/link}, avec les mêmes crêtes rouges et les mêmes ruisseaux froids que {link:lakeshire}Lakeshire{/link} connaît encore. Ce sont les {link:dark-iron-dwarves}Sombrefer{/link} qui y mirent fin. Exilés d'{link:ironforge}Ironforge{/link} après la guerre des trois clans nains, ils bâtirent une cité dans ces montagnes et lui donnèrent le nom de leur thane-sorcier, {link:ruins-of-thaurissan}Thaurissan{/link}. Quand les Bronzebeard et les Wildhammer marchèrent contre eux, Thaurissan chercha une arme dans les profondeurs du monde, et c'est {red:ragnaros}Ragnaros{/red}, le seigneur du feu, qu'il appela. La venue de Ragnaros fit fondre les montagnes sur des lieues à la ronde. La cité sombrefer fut ruinée, un volcan s'éleva là où la terre s'était fendue, et le pays au sud se mit à brûler. Il n'a jamais cessé de brûler.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Les Steppes n'appartiennent à aucune couronne. Les orcs du {link:blackrock-clan}clan Blackrock{/link} tiennent le cœur du pays depuis leur place forte sous la montagne, et leurs bandes de guerre descendent vers le sud par le {link:blackrock-pass}Défilé des Blackrock{/link} pour tourmenter {link:lakeshire}Lakeshire{/link}. Des ogres Firegut gardent pour eux les mines du {link:dreadmaul-rock}Rocher des Cognepeurs{/link}. Des draconiens noirs nichent le long des falaises de l'est et dans les collines calcinées du sud-ouest. Des espions et des marche-feu sombrefer hantent encore les ruines de leur ancienne cité, et le feu et la pierre vivants arpentent les plaines.

Face à tout cela, {link:kingdom-of-stormwind}Stormwind{/link} ne garde qu'un seul avant-poste : {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link}, sur une crête au sud-est, où le maréchal {link:marshal-maxwell}Maxwell{/link} tient bon avec une poignée de soldats et d'érudits et attend un régent qui n'envoie pas d'armée. Le maréchal qui les commandait autrefois, {red:reginald-windsor}Reginald Windsor{/red}, a disparu dans la montagne avec tout ce qu'il avait appris de l'ennemi. Loin au nord, sous la crête, un petit camp à la {link:flame-crest}Corniche des flammes{/link} abrite des marchands, des chercheurs et des parias de tous les peuples, et donne à la {link:horde}Horde{/link} un point d'appui qui lui est propre.

Ce que les guetteurs de la Veille ont commencé à comprendre, c'est que les orcs ne sont pas les vrais maîtres des Steppes. Quelque chose de plus ancien et de bien plus rusé pousse les {link:blackrock-mountain}Blackrock{/link} par-derrière, et ses griffes pourraient aller plus loin que quiconque à {link:stormwind-city}Stormwind{/link} ne veut le croire.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les {link:blackrock-clan}orcs Blackrock{/link}.{/b} Le plus ancien des clans de guerre, qui garde encore les coutumes de l'ancienne {link:horde}Horde{/link}. Leurs soldats, leurs sorciers et leurs démonistes remplissent les plaines centrales et la forteresse sous la montagne, et leurs worgs courent avec eux.
• {b}Les ogres Firegut.{/b} Alliés des {link:blackrock-mountain}Blackrock{/link}, ils tiennent le {link:dreadmaul-rock}Rocher des Cognepeurs{/link} et gardent ouvertes ses lignes de ravitaillement.
• {b}Les draconiens noirs.{/b} Dragonnets, drakônides, wyrmides et drakes errent sur les falaises de l'est et le long du {link:terror-wing-path}Chemin de l'Aile de la terreur{/link}. Leurs parents aux écailles de flamme tiennent {link:draco-dar}Draco'dar{/link} au sud-ouest.
• {b}Les {link:dark-iron-dwarves}Sombrefer{/link}.{/b} Espions, agents et marche-feu de {link:ruins-of-thaurissan}Thaurissan{/link} veillent sur la cité en ruine, et des saccageurs de guerre de leur fabrication rôdent dans les cendres.
• {b}Les enfants du feu.{/b} Des élémentaires d'obsidienne et de flamme errent dans le pays, vestiges du feu qui l'a façonné.
• {b}Les gens de {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link}.{/b} Des soldats de {link:stormwind-city}Stormwind{/link}, un éclaireur {link:night-elves}elfe de la nuit{/link}, une {link:gnomes}gnome{/link} des mages et une agente de la noblesse, qui tiennent tous une seule crête.
• {b}Les gens de la {link:flame-crest}Corniche des flammes{/link}.{/b} Des marchands gobelins, un chercheur de trésors gnome, un enchanteur elfe, un {link:dwarves}nain{/link} ivre et les orcs de la Horde, abrités ensemble sous la crête du nord.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le pays vert.{/b} Il y a longtemps, les Steppes faisaient partie de la chaîne des {link:redridge-mountains}Carmines{/link}, et les {link:dark-iron-dwarves}Sombrefer{/link} élevèrent leur cité parmi ses sommets.
• {b}L'invocation.{/b} Le thane-sorcier {link:ruins-of-thaurissan}Thaurissan{/link} appela Ragnaros. Les montagnes fondirent, le {link:blackrock-mountain}Mont Blackrock{/link} naquit, et la terre devint les Steppes ardentes.
• {b}Les guerres de la {link:horde}Horde{/link}.{/b} Les orcs firent de la montagne leur forteresse. Pendant la {link:second-war}Deuxième Guerre{/link}, l'{link:alliance}Alliance{/link} monta vers le nord pour l'assiéger, et au pied du Pic Blackrock, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} tua {link:anduin-lothar}Anduin Lothar{/link}. {link:turalyon}Turalyon{/link} reprit le commandement de Lothar et brisa la Horde.
• {b}Le retour des Blackrock.{/b} Les Blackrock qui échappèrent aux camps d'internement retournèrent à la montagne qui porte leur nom, et ils tiennent les Steppes depuis.
• {b}Le temps présent.{/b} Le maréchal Windsor réunit la preuve de qui commande vraiment les Blackrock, et il disparut avant de pouvoir la remettre. La {link:morgan-s-vigil}Veille de Morgan{/link} monte la garde, et attend.]=],
		},
		{
			title = "Légendes des Steppes",
			text = [=[• On dit que les reliques de {link:ruins-of-thaurissan}Thaurissan{/link} qui jonchent la cité en ruine gardent la mémoire de l'invocation. Ceux qui les touchent emportent des visions du jour où la montagne est née.
• À {link:morgan-s-vigil}la Veille{/link}, les soldats parlent d'Ironfoe, le marteau que portait le maréchal Windsor. Ils disent qu'il fut forgé par un maître sombrefer pour l'un de ses ancêtres, et qu'il a un jumeau.
• Les orcs des Steppes élèvent et dressent leurs worgs dans le Pic {link:blackrock-mountain}Blackrock{/link}. Peu importe combien on en tue, les meutes ne semblent jamais diminuer.
• Dans le camp de la {link:flame-crest}Corniche des flammes{/link}, un gobelin et une {link:gnomes}gnome{/link} se disputent des œufs de dragon, un gobelin vend des chiots worgs aux riches, et une sœur traque son propre frère pour la prime sur sa tête.]=],
		},
	},
})

Translate("frFR", "morgan-s-vigil", {
	title = "Veille de Morgan",
	aliases = { "la Veille" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Veille de Morgan est le dernier avant-poste de {link:kingdom-of-stormwind}Stormwind{/link} dans {link:burning-steppes}les Steppes{/link} ardentes. Elle se dresse sur une haute crête au sud-est, au-dessus d'une pente où rôdent les draconiens noirs, et elle domine tout le pays brûlant jusqu'à la montagne. Un maître des griffons y garde des oiseaux prêts pour le vol du retour. Le maréchal {link:marshal-maxwell}Maxwell{/link} y commande, avec quelques soldats, un éclaireur {link:night-elves}elfe de la nuit{/link}, une {link:gnomes}gnome{/link} envoyée par les mages et une dame au service d'un comte. Ils formaient autrefois la compagnie du maréchal Windsor. Aujourd'hui, ils sont simplement ce qui reste.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit qui était {link:morgan-stern}Morgan{/link}, ni pourquoi la Veille porte ce nom.]=],
		},
	},
})

Translate("frFR", "flame-crest", {
	title = "Corniche des flammes",
	sections = {
		{
			title = "Résumé",
			text = [=[La Corniche des flammes est un petit camp niché dans une grotte sous la crête nord des Steppes, au nord-ouest du {link:dreadmaul-rock}Rocher des Cognepeurs{/link}. La {link:horde}Horde{/link} y entretient un maître des coursiers du vent et un aubergiste, mais le camp n'appartient à aucun peuple. Des gobelins y font commerce d'animaux et traquent leurs propres parents. Une {link:gnomes}gnome{/link} suit de vieilles légendes naines en quête de richesse. Un elfe de {link:quel-thalas}Quel'Thalas{/link} vend des enchantements à prix amer. Un {link:dwarves}nain{/link} ivre nommé {link:ragged-john}Ragged John{/link} est assis parmi eux, et ceux qui cherchent le maréchal Windsor viennent entendre son histoire.]=],
		},
	},
})

Translate("frFR", "blackrock-stronghold", {
	title = "Bastion des Blackrock",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bastion des Blackrock est la forteresse des {link:blackrock-clan}orcs Blackrock{/link}, sur les plaines ouvertes au sud de la montagne. Ses maîtres de guerre y entraînent les soldats du clan, et ses démonistes y entretiennent leurs feux jour et nuit. Depuis le bastion, les bandes de guerre marchent vers le sud, vers les {link:redridge-mountains}Carmines{/link}. C'est aussi un refuge pour ceux qui trahissent la {link:horde}Horde{/link} de {link:thrall}Thrall{/link} : l'{link:orcs}orc{/link} {link:grark-lorkrub}Grark Lorkrub{/link} y siège sous la protection du clan, et il se croit en sécurité. Un soldat {link:blackrock-mountain}Blackrock{/link} nommé Ugkragg s'attarde près de ses murs, humilié par quelque défaite qu'aucun registre ne nomme.]=],
		},
	},
})

Translate("frFR", "dreadmaul-rock", {
	title = "Rocher des Cognepeurs",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rocher des Cognepeurs est un grand éperon de pierre à l'est des Steppes, riche en minerai et criblé de grottes et de mines. Les ogres Firegut le tiennent pour les {link:blackrock-mountain}Blackrock{/link}, et leurs mages et leurs brutes gardent chaque sentier. Une section de la {link:horde}Horde{/link} vint ici pour découvrir quels rites étranges pratiquaient les ogres. Aucun d'eux ne revint. L'une des leurs, Sha'ni Proudtusk, fut enchaînée sur un autel au sommet par l'{link:ogres}ogre{/link} {link:krom-grul}Krom'Grul{/link}, et son esprit n'a pas quitté ce lieu. C'est au sommet de ce même rocher que les soldats de {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} plantèrent un jour la tête d'un seigneur ogre sur une pique.]=],
		},
	},
})

Translate("frFR", "ruins-of-thaurissan", {
	title = "Ruines de Thaurissan",
	aliases = { "Thaurissan", "les ruines de Thaurissan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines de Thaurissan sont tout ce qui reste à la surface de la première cité des {link:dark-iron-dwarves}Sombrefer{/link}, au milieu des Steppes. Elle fut engloutie quand son propre thane appela le seigneur du feu. Des murs brisés et des salles effondrées couvent encore parmi les cendres. Des reliques de la cité gisent éparses dans les décombres, et l'on dit qu'elles gardent la mémoire de ce qui arriva ici. Les Sombrefer n'ont pas oublié l'endroit : des espions, des agents et des marche-feu de leur empereur le gardent, et des saccageurs de guerre arpentent ses rues. Quelque part parmi les pierres repose la Tablette des Sept, écrite à la louange de sept nains d'un grand savoir.]=],
		},
	},
})

Translate("frFR", "altar-of-storms-burning-steppes", {
	title = "Autel des tempêtes (Steppes ardentes)",
	sections = {
		{
			title = "Résumé",
			text = [=[À l'extrême ouest des Steppes, à l'ombre de la montagne, se dresse un Autel des tempêtes. Des démonistes {link:blackrock-mountain}Blackrock{/link} se rassemblent autour et y accomplissent leurs rites. Son pouvoir en attire d'autres aussi. Le démoniste {link:mor-zul-bloodbringer}Mor'zul Bloodbringer{/link} campe tout près avec son serviteur {link:gorzeeki-wildeyes}Gorzeeki Wildeyes{/link} et étudie l'énergie de l'autel à des fins qui lui sont propres, et c'est ici que les démonistes viennent le trouver quand ils cherchent à lier une monture des plaines brûlantes de Xoroth.]=],
		},
	},
})

Translate("frFR", "pillar-of-ash", {
	title = "Le Pilier de cendres",
	aliases = { "Pilier de cendres" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Pilier de cendres est une haute tour des {link:blackrock-mountain}Blackrock{/link} au sud des Steppes, qui domine les camps où les orcs rassemblent leurs soldats et leurs worgs pour la marche sur les {link:redridge-mountains}Carmines{/link}. Des sorciers et des tueurs patrouillent le terrain alentour. À l'ouest du {link:dreadmaul-rock}Rocher des Cognepeurs{/link}, dans une place forte Blackrock près du pilier, le seigneur {link:ogres}ogre{/link} {link:gor-tesh}Gor'tesh{/link} régnait jadis sur les Firegut, loin du rocher que gardaient ses ogres.]=],
		},
	},
})

Translate("frFR", "terror-wing-path", {
	title = "Chemin de l'Aile de la terreur",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Chemin de l'Aile de la terreur longe les falaises de l'est des Steppes, depuis les pentes au pied de {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} jusqu'à l'extrême nord-est. C'est le terrain de chasse du vol noir. Des dragonnets grouillent sur les pentes basses, des drakônides et des wyrmides tiennent les hauteurs, et des drakes noirs tournoient au-dessus. Les soldats de la Veille doivent combattre ces draconiens chaque jour rien que pour tenir leur crête. Au-delà du chemin, à son extrémité nord, se trouve la grotte appelée {link:slither-rock}Roc sinueux{/link}.]=],
		},
	},
})

Translate("frFR", "draco-dar", {
	title = "Draco'dar",
	sections = {
		{
			title = "Résumé",
			text = [=[Draco'dar est une région de collines calcinées au sud-ouest des Steppes. Elle appartient aux draconiens des couvées aux écailles de flamme, plus forts et plus féroces que leurs parents de l'est. Des drakes Searscale survolent les collines, et l'on dit qu'un grand dragon nommé Hematos rôde parmi eux. Les voyageurs n'entrent pas seuls à Draco'dar, et peu y entrent tout court.]=],
		},
	},
})

Translate("frFR", "slither-rock", {
	title = "Roc sinueux",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Roc sinueux est une grotte isolée à l'extrême nord-est des Steppes, au-delà du bout du {link:terror-wing-path}Chemin de l'Aile de la terreur{/link}. Une seule créature y demeure : {link:cyrus-therepentous}Cyrus Therepentous{/link}, un serviteur du vol noir, qui garde un drake à lui comme gardien. Il n'accueille pas les visiteurs. Ceux qu'il choisit de ne pas dévorer, il s'en sert.]=],
		},
	},
})

Translate("frFR", "blackrock-pass", {
	title = "Défilé des Blackrock",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Défilé des Blackrock est la route entre {link:burning-steppes}les Steppes{/link} ardentes et {link:redridge-mountains}les Carmines{/link}, gardée par une porte du côté des Carmines. Par là, les bandes de guerre {link:blackrock-mountain}Blackrock{/link} descendent au sud pour fondre sur {link:lakeshire}Lakeshire{/link}, et par là, les adjoints de {link:stormwind-city}Stormwind{/link} montent au nord vers {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link}. C'est une frontière tranchée. D'un côté s'étendent les collines rouges et le lac. De l'autre s'étend la cendre, et des créatures de feu qui ont tué bien des voyageurs aventurés trop loin.]=],
		},
	},
})

Translate("frFR", "marshal-maxwell", {
	title = "Maréchal Maxwell",
	subtitle = "Commandant de la Veille de Morgan",
	found = "La Veille de Morgan, au sud-est des Steppes",
	hint = [=[Parlez au maréchal qui tient la dernière crête de Stormwind dans les Steppes ardentes.]=],
	allegiance = "Royaume de Stormwind · Armée de Stormwind",
	aliases = { "Maxwell" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maréchal Maxwell commande {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link}, le seul point d'appui de {link:stormwind-city}Stormwind{/link} dans {link:burning-steppes}les Steppes{/link} ardentes. Il prit le commandement quand le maréchal Windsor disparut, et il tient sa crête avec quelques soldats contre les orcs, les ogres et les dragons. Il est heureux de voir tout membre de l'{link:alliance}Alliance{/link} venir si loin. Il est aussi devenu amer. Il a maintes fois demandé de l'aide à Stormwind, et Stormwind lui a envoyé des adjoints au lieu d'armées.]=],
		},
		{
			title = "Importance",
			text = [=[Maxwell se tient au seuil de l'ennemi. Depuis {link:morgan-s-vigil}la Veille{/link}, il voit la forteresse des {link:blackrock-mountain}Blackrock{/link} et la montagne qui la domine, et il sait mieux que quiconque dans la capitale ce qui s'y rassemble. Par lui se poursuit la longue recherche du maréchal Windsor, et de la vérité que Windsor portait.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tient {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} contre les {link:blackrock-clan}orcs Blackrock{/link}, les ogres Firegut et les draconiens noirs.
• Il envoie des adjoints découvrir le sort du maréchal Windsor, d'abord auprès de {link:ragged-john}Ragged John{/link}, puis dans les profondeurs de {link:blackrock-mountain}Blackrock{/link}.
• Il prépare la guerre contre les maîtres du Pic Blackrock à partir des cartes et des rapports qu'on lui apporte.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Maxwell avant {link:morgan-s-vigil}la Veille{/link}, et rien sur sa famille.]=],
		},
	},
	chapters = {
		{
			title = "Encore un adjoint",
			hint = [=[Venez à la Veille de Morgan en tant qu'adjoint par intérim de Stormwind.]=],
			text = [=[Quand l'adjoint du magistrat {link:magistrate-solomon}Solomon{/link} arriva avec le décret du régent, Maxwell éclata de rire. L'adjoint n'était pas le premier. {link:stormwind-city}Stormwind{/link} en avait envoyé d'autres avant, et les avait perdus un par un tandis que le royaume se querellait sur les preuves. Maxwell avait eu jadis de telles preuves à portée de main. Le maréchal Windsor avait réuni une grande somme de connaissances sur les {link:blackrock-mountain}Blackrock{/link}, et tout avait disparu avec lui. Maxwell envoya le nouveau venu au nord trouver le seul homme qui avait été aux côtés de Windsor.]=],
		},
		{
			title = "Un maréchal enchaîné",
			hint = [=[Découvrez ce qu'il advint du maréchal Windsor dans les profondeurs de Blackrock.]=],
			text = [=[{link:ragged-john}Ragged John{/link} jurait que Windsor était vivant, prisonnier des {link:dark-iron-dwarves}Sombrefer{/link}. Maxwell envoya son adjoint dans les {red:blackrock-depths}Profondeurs de Blackrock{/red} pour ramener le maréchal, ou la preuve de sa mort. Les nouvelles qui revinrent étaient pires que l'un et l'autre. Windsor vivait, mais ses notes étaient perdues, et il délirait au sujet de sots et d'ennemis cachés. Maxwell baissa la tête et pleura un fier guerrier qui, pensait-il, avait perdu la raison.]=],
		},
		{
			title = "Windsor libéré",
			hint = [=[Aidez le maréchal Windsor à s'évader de la prison des Sombrefer.]=],
			text = [=[Windsor n'était pas fou. Il sortit de la montagne avec ses notes volées entre les mains, et il traversa {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} comme une tempête, en route pour {link:stormwind-city}Stormwind{/link}. Il confronterait le régent, disait-il, ainsi que la dame qui se tient aux côtés du régent. Maxwell fit dire que son adjoint devait le rejoindre aux portes de la cité, et ne pas y aller seul. Ce que Windsor comptait révéler ébranlerait le royaume jusque dans ses fondations.]=],
		},
		{
			title = "Les maîtres démasqués",
			hint = "Suivez la grande mascarade jusqu'à son terme.",
			text = [=[Dans la salle du trône du donjon de {link:stormwind-city}Stormwind{/link}, Windsor présenta ses preuves devant la cour, et {link:katrana-prestor}Dame Katrana Prestor{/link} rejeta sa forme humaine. Elle était {link:onyxia}Onyxia{/link}, fille d'{link:deathwing}Aile-de-mort{/link}, et depuis aussi longtemps qu'elle conseillait le régent, le vol noir avait l'oreille de Stormwind. Windsor y mourut. À {link:morgan-s-vigil}la Veille{/link}, Maxwell comprit enfin pourquoi ses suppliques étaient restées sans réponse. Les dragons commandaient les {link:blackrock-mountain}Blackrock{/link} depuis la montagne, et ils avaient réduit Stormwind au silence depuis sa propre cour.]=],
		},
		{
			title = "La guerre du Pic",
			hint = [=[Apportez à Maxwell des nouvelles de ceux qui commandent vraiment le Pic Blackrock.]=],
			text = [=[Une espionne gobeline qui s'était glissée dans le Pic envoya une carte à Maxwell. Elle confirma ce qu'il soupçonnait. Les {link:blackrock-mountain}Blackrock{/link} étaient des bêtes de somme et de la chair à canon pour le vol noir, et leur vrai seigneur était {red:nefarian}Nefarian{/red}, fils d'{link:deathwing}Aile-de-mort{/link}. Maxwell désigna pour la mort le maître de guerre, le grand seigneur {link:ogres}ogre{/link} et le suzerain de la citadelle. Plus tard, une lettre fut prise sur le corps d'un draconien du Pic, écrite par son supérieur, le {red:general-drakkisath}général Drakkisath{/red}. Maxwell désigna aussi le général. Il disait que la guerre se livrait sur deux fronts : au sein de {link:stormwind-city}Stormwind{/link}, et ici, aux portes de l'ennemi.]=],
		},
	},
	mentions = {
		{
			text = [=[Les vrais maîtres, de la part du magistrat {link:magistrate-solomon}Solomon{/link}]=],
		},
		{
			text = [=[Les vrais maîtres, le récit de {link:ragged-john}Ragged John{/link}]=],
		},
		{ text = "Le maréchal Windsor" },
		{ text = "Espoir abandonné" },
		{ text = "Évasion !, qui s'achève à son poste" },
		{ text = "Rendez-vous à {link:stormwind-city}Stormwind{/link}" },
		{ text = "Message pour Maxwell" },
		{ text = "La mission de Maxwell" },
		{ text = "Les ordres du général Drakkisath" },
		{ text = "La fin du général Drakkisath" },
	},
	bonds = {
		{ id = "reginald-windsor", name = "Reginald Windsor", note = "son commandant disparu" },
		{ id = "ragged-john", name = "Ragged John", note = "un témoin qu'il traite de lâche" },
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "lui envoie des adjoints" },
		{ id = "helendis-riverhorn", name = "Helendis Riverhorn", note = "son éclaireur" },
		{ id = "oralius", name = "Oralius", note = "un soldat de la Veille" },
		{ id = "nefarian", name = "Nefarian", note = "le vrai maître du Pic" },
	},
})

Translate("frFR", "helendis-riverhorn", {
	title = "Helendis Riverhorn",
	subtitle = "Éclaireur de la Veille de Morgan",
	found = [=[Le bord est de la Veille de Morgan, au-dessus des pentes des draconiens]=],
	hint = [=[Parlez à l'elfe de la nuit qui surveille les draconiens depuis le bord de la Veille de Morgan.]=],
	allegiance = "Alliance · Veille de Morgan",
	aliases = { "Helendis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Helendis Riverhorn est un {link:night-elves}elfe de la nuit{/link} qui sert à {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link}. Il se tient au bord de la crête, au-dessus des pentes où se rassemblent les draconiens noirs, et il les observe. Il invoque Cénarius quand il souhaite du bien à un soldat. C'est lui qui vit clairement le premier ce qu'étaient vraiment les {link:blackrock-clan}orcs Blackrock{/link}, et qui envoya cette connaissance au sud, à {link:lakeshire}Lakeshire{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Helendis déclencha la chaîne d'événements qui devait un jour atteindre la salle du trône de {link:stormwind-city}Stormwind{/link}. Les humains avaient toujours cru que les {link:blackrock-mountain}Blackrock{/link} étaient sauvages par nature. Helendis découvrit qu'on les poussait. La rage qui les emplit, écrivit-il, est nourrie par le vol noir, et ce sont les dragons qui sont leurs vrais maîtres.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il combat les draconiens qui pressent {link:morgan-s-vigil}la Veille{/link}.
• Il écrit au magistrat {link:magistrate-solomon}Solomon{/link} au sujet des vrais maîtres des {link:blackrock-mountain}Blackrock{/link}.
• Il suit jusqu'à leur source les meutes sans fin des worgs Blackrock.]=],
		},
	},
	chapters = {
		{
			title = "Les draconiens sous la crête",
			hint = "Repoussez les draconiens sous la Veille de Morgan.",
			text = [=[Helendis ne voulait pas parler de choses graves à un étranger. L'étranger devait d'abord prouver qu'il pouvait tenir tête aux draconiens. Ce n'est que lorsque dragonnets, drakônides, wyrmides et un drake furent tombés sur les pentes en contrebas qu'il jugea le nouveau venu prêt à en entendre davantage.]=],
		},
		{
			title = "Une lettre pour Lakeshire",
			hint = "Portez la lettre d'Helendis au sud, jusqu'à Lakeshire.",
			text = [=[Ce qu'Helendis avait découvert sur la terre natale des {link:blackrock-mountain}Blackrock{/link} ne pouvait rester sur une seule crête. Il scella une lettre pour le magistrat {link:magistrate-solomon}Solomon{/link} : les orcs n'étaient pas leurs propres maîtres, et c'était le vol noir qui les emplissait de rage. Solomon pleura en lisant ce que cela signifiait pour sa ville, et il la fit suivre à {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "La mère des worgs",
			hint = "Cherchez la source des worgs dans le Pic Blackrock.",
			text = [=[Les worgs {link:blackrock-mountain}Blackrock{/link} ne diminuaient jamais, peu importe combien on en tuait. Les éclaireurs d'Helendis apprirent que les bêtes étaient élevées et dressées dans le Pic. Il envoya un chasseur trouver la source, et il cria un nom au départ du chasseur : Halycon. C'était une créature de magie noire, et Helendis demanda que personne ne la pleure.]=],
		},
	},
	mentions = {
		{ text = "La menace draconique" },
		{ text = "Les vrais maîtres" },
		{ text = "Abattez-la" },
	},
	bonds = {
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "a reçu sa lettre" },
		{ id = "marshal-maxwell", name = "Maréchal Maxwell", note = "son commandant" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "a eu vent de son avertissement" },
	},
})

Translate("frFR", "ragged-john", {
	title = "Ragged John",
	subtitle = "Témoin de la montagne",
	found = "La Corniche des flammes, sous la crête du nord",
	hint = [=[Trouvez le nain ivre qui se cache dans une grotte à la Corniche des flammes.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Ragged John est un {link:dwarves}nain{/link} qui vit à la {link:flame-crest}Corniche des flammes{/link}, dans la grotte sous la crête du nord, et il est rarement sobre. Il était aux côtés du maréchal Windsor le jour où le maréchal disparut. Le maréchal {link:marshal-maxwell}Maxwell{/link} le traite de lâche. John préfère dire qu'il est un peu négligé, et que les nains ne s'enivrent jamais.]=],
		},
		{
			title = "Importance",
			text = [=[John est le seul témoin du sort de Windsor. Son récit, si difficile à suivre soit-il, apprit à {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} que Windsor vivait encore, et où le chercher.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il marcha avec le maréchal Windsor jusque dans le {link:blackrock-mountain}Mont Blackrock{/link}.
• Il se glissa dans l'ombre quand les orcs attaquèrent.
• Il se rend de temps à autre dans le Pic Blackrock et écoute ce que disent les orcs.]=],
		},
	},
	chapters = {
		{
			title = "Le récit de Ragged John",
			hint = "Apprenez de Ragged John ce qu'il advint du maréchal Windsor.",
			text = [=[John le raconte longuement. Windsor était d'humeur sombre ce jour-là et répétait que quelque chose clochait. Au cœur de la montagne, les {link:blackrock-mountain}Blackrock{/link} tombèrent sur eux, et John se cacha. Windsor tint bon avec Ironfoe, le marteau tueur d'orcs que {link:franclorn-forgewright}Franclorn Forgewright{/link} fabriqua pour l'un de ses aïeux, et il était encore debout, trempé de sang d'{link:orcs}orc{/link}, quand les combats cessèrent. Puis vinrent les {link:dark-iron-dwarves}Sombrefer{/link}, par centaines. Ils ne le tuèrent pas, peut-être parce que son aïeul avait été un ami de leur peuple. Ils le firent prisonnier, et leur chef prit Ironfoe. John ne le revit jamais.]=],
		},
		{
			title = "Le lait de la mère",
			hint = [=[Apportez à Ragged John un échantillon vivant du poison le plus mortel du Pic.]=],
			text = [=[Dans le Pic, John entendit les orcs parler d'un poison qu'ils appellent le lait de la mère, d'après la grande araignée Mère Smolderweb. Il le voulait, et pas tiré d'une glande : il devait venir frais, dans les veines de quelqu'un qu'elle avait mordu. Quand il l'eut extrait, il expliqua qu'il en ferait sa meilleure bière.]=],
		},
	},
	mentions = {
		{ text = "Les vrais maîtres" },
		{ text = "Le lait de la mère" },
	},
	bonds = {
		{ id = "reginald-windsor", name = "Reginald Windsor", note = "le maréchal avec qui il marcha" },
		{ id = "marshal-maxwell", name = "Maréchal Maxwell", note = "le traite de lâche" },
		{ id = "franclorn-forgewright", name = "Franclorn Forgewright", note = "fabriqua le marteau de Windsor" },
	},
})

Translate("frFR", "oralius", {
	title = "Oralius",
	subtitle = "Soldat de la Veille de Morgan",
	found = "Veille de Morgan",
	hint = [=[Parlez au nain de la Veille de Morgan qui parle à un ami que personne d'autre ne voit.]=],
	allegiance = "Royaume de Stormwind · Veille de Morgan",
	sections = {
		{
			title = "Résumé",
			text = [=[Oralius est un soldat {link:dwarves}nain{/link} de {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} qui prépare la guerre contre les ogres Firegut avec un grand zèle. Il parle aussi au capitaine Winky, un ami que personne d'autre ne peut voir, et il garde une collection d'oreilles d'ogres. Il confie qu'il est le seul sain d'esprit à la Veille. Les autres ne sont pas de cet avis.]=],
		},
		{
			title = "Importance",
			text = [=[Quoi que la guerre ait pris à son esprit, Oralius n'a pas perdu sa haine de l'ennemi. Sa campagne contre le {link:dreadmaul-rock}Rocher des Cognepeurs{/link} est le coup le plus féroce que {link:morgan-s-vigil}la Veille{/link} ait porté.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il ordonne des frappes contre les ogres Firegut du {link:dreadmaul-rock}Rocher des Cognepeurs{/link}.
• Il désigne pour la mort le seigneur {link:ogres}ogre{/link} {link:gor-tesh}Gor'tesh{/link}.
• Il collectionne les médaillons des {link:blackrock-clan}orcs Blackrock{/link} pour aller avec ses oreilles d'ogres.]=],
		},
	},
	chapters = {
		{
			title = "Une tête sur une pique",
			hint = "Aidez Oralius à briser le moral des ogres Firegut.",
			text = [=[Quand {link:gor-tesh}Gor'tesh{/link} tomba, Oralius planta la tête du seigneur {link:ogres}ogre{/link} sur une pique et la fit porter au sommet du {link:dreadmaul-rock}Rocher des Cognepeurs{/link}, certain que la vue ferait fuir les ogres de terreur. Il demanda ensuite si quelqu'un en avait peint un tableau.]=],
		},
	},
	mentions = {
		{ text = "Éteindre les Firegut" },
		{ text = "{link:gor-tesh}Gor'tesh{/link}, le seigneur brute" },
		{ text = "Tête d'{link:ogres}ogre{/link} sur un bâton = fête" },
		{ text = "CINQUANTE ! OUAIS !" },
		{ text = "La bonne camelote" },
	},
	bonds = {
		{ id = "gor-tesh", name = "Gor'tesh", note = "le seigneur ogre qu'il désigna pour la mort" },
		{ id = "marshal-maxwell", name = "Maréchal Maxwell", note = "son commandant" },
	},
})

Translate("frFR", "jalinda-sprig", {
	title = "Jalinda Sprig",
	subtitle = "Mage gnome de la Veille de Morgan",
	found = "Veille de Morgan",
	hint = [=[Parlez à la gnome de la Veille de Morgan dont les mages reviennent sans cesse roussis de la montagne.]=],
	allegiance = "Alliance · Veille de Morgan",
	sections = {
		{
			title = "Résumé",
			text = [=[Jalinda Sprig est une {link:gnomes}gnome{/link} de {link:morgan-s-vigil}la Veille{/link} de {link:morgan-stern}Morgan{/link} qui mène une expédition de mages dans le {link:blackrock-mountain}Mont Blackrock{/link}. Ou qui essaie. Les cinq derniers qu'elle a envoyés sont revenus brûlés, quand ils sont revenus. Elle est anxieuse et bienveillante, et prompte à craindre le pire.]=],
		},
		{
			title = "Importance",
			text = [=[L'expédition de Jalinda fut parmi les premières à apprendre que les feux sous la montagne ont un maître.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle cherche à ouvrir à son expédition la route des {red:blackrock-depths}Profondeurs de Blackrock{/red}.
• Elle envoie de l'aide contre le {link:overmaster-pyron}surmaître Pyron{/link}, qui garde la carrière de la montagne.]=],
		},
	},
	chapters = {
		{
			title = "Incendius",
			hint = "Découvrez qui relève Pyron de ses cendres.",
			text = [=[{link:overmaster-pyron}Pyron{/link} prononça un nom en mourant : Incendius. Jalinda le connaissait, et elle déglutit. On disait que Lord Incendius servait {red:ragnaros}Ragnaros{/red}. Quand on lui rapporta qu'Incendius lui-même avait nommé le seigneur du feu, elle ne dit plus rien, et s'abîma dans ses pensées.]=],
		},
	},
	mentions = {
		{ text = "Le surmaître {link:overmaster-pyron}Pyron{/link}" },
		{ text = "Incendius !" },
	},
	bonds = {
		{ id = "overmaster-pyron", name = "Surmaître Pyron", note = "le gardien de la carrière" },
		{ id = "ragnaros", name = "Ragnaros", note = "le nom qu'elle redoute" },
	},
})

Translate("frFR", "mayara-brightwing", {
	title = "Mayara Brightwing",
	subtitle = "Agente du comte Ridgewell",
	found = "Veille de Morgan",
	hint = [=[Parlez à la femme de la Veille de Morgan qui sert un collectionneur de Stormwind.]=],
	allegiance = "Maison Ridgewell",
	sections = {
		{
			title = "Résumé",
			text = [=[Mayara Brightwing est une agente du {red:count-remington-ridgewell}comte Remington Ridgewell{/red}, un noble de {link:stormwind-city}Stormwind{/link} qui entretient un musée familial. Il l'envoya dans {link:burning-steppes}les Steppes{/link} fouiller {link:ruins-of-thaurissan}les ruines de Thaurissan{/link} à la recherche d'objets d'art. Ce qu'elle a trouvé se trouve ailleurs : tout en haut du Pic {link:blackrock-mountain}Blackrock{/link}, dans une salle où les {link:dark-iron-dwarves}Sombrefer{/link} gardaient autrefois leurs trésors.]=],
		},
		{
			title = "Importance",
			text = [=[Même dans {link:burning-steppes}les Steppes{/link} ardentes, les nobles de {link:stormwind-city}Stormwind{/link} ont des agents. Mayara sert les collections de la {link:house-of-nobles}Chambre des nobles{/link} tandis que des soldats se battent pour leur vie.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle explora les {link:ruins-of-thaurissan}Ruines de Thaurissan{/link} pour son protecteur.
• Elle cherche l'Agrafe de Doomrigger, une relique sertie de joyaux laissée dans l'ancien hall de la Fortune du Pic.]=],
		},
	},
	mentions = {
		{ text = "Mayara Brightwing" },
		{ text = "L'Agrafe de Doomrigger" },
		{ text = "Livraison à Ridgewell" },
	},
	bonds = {
		{ id = "count-remington-ridgewell", name = "Comte Remington Ridgewell", note = "son protecteur" },
	},
})

Translate("frFR", "maxwort-uberglint", {
	title = "Maxwort Uberglint",
	subtitle = "Chercheur des Sept",
	found = "Corniche des flammes",
	hint = [=[Parlez au chercheur de trésors de la Corniche des flammes qui suit les légendes des Sept.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Maxwort Uberglint fut attiré dans {link:burning-steppes}les Steppes{/link} ardentes par les vieux récits des Sept, des nains d'un grand savoir et d'une grande puissance. Il ne cache pas pourquoi. Le savoir et la puissance apportent la richesse, et c'est la richesse qu'il veut. Il convoite aussi une gemme que les {link:dark-iron-dwarves}Sombrefer{/link} gardent dans leur chambre forte, une pierre de la taille d'un poing.]=],
		},
		{
			title = "Importance",
			text = [=[Maxwort garde vivant un vieux récit de {link:ruins-of-thaurissan}Thaurissan{/link}. La Tablette des Sept repose encore dans les ruines, et il en veut les mots.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il cherche une copie de la Tablette des Sept dans les {link:ruins-of-thaurissan}Ruines de Thaurissan{/link}.
• Il a tenté pendant des années d'acheter le Cœur de la montagne aux {link:dark-iron-dwarves}Sombrefer{/link}, sans succès.]=],
		},
	},
	mentions = {
		{ text = "La Tablette des Sept" },
		{ text = "Le Cœur de la montagne" },
	},
	bonds = {
		{ id = "mathredis-firestar", name = "Mathredis Firestar", note = "partage le camp de la Corniche des flammes" },
	},
})

Translate("frFR", "yuka-screwspigot", {
	title = "Yuka Screwspigot",
	subtitle = "Sœur de Ribbly",
	found = "Corniche des flammes",
	hint = [=[Parlez à la gobeline de la Corniche des flammes qui traque son propre frère.]=],
	allegiance = "La famille Screwspigot",
	sections = {
		{
			title = "Résumé",
			text = [=[Yuka Screwspigot est venue à la {link:flame-crest}Corniche des flammes{/link} pour retrouver son frère Ribbly. Ribbly a gaspillé l'argent de la famille dans une combine après l'autre, et sa dernière combine lui a valu une prime sur sa tête de la part du {link:baron-revilgaz}baron Revilgaz{/link} de {link:booty-bay}Baie-du-Butin{/link}. Pour la première fois de sa vie, Ribbly vaut quelque chose. Yuka compte bien encaisser.]=],
		},
		{
			title = "Importance",
			text = [=[Les Screwspigot montrent que la famille, pour certains gobelins, est une affaire de comptes. Ribbly s'est enfui dans les {red:blackrock-depths}Profondeurs de Blackrock{/red}, et sa sœur l'a suivi jusqu'au seuil.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle a suivi la piste de Ribbly jusqu'aux {link:burning-steppes}Steppes ardentes{/link} et fait venir des mercenaires.
• Elle prendra son frère vivant, ou sa tête s'il refuse de venir.]=],
		},
	},
	mentions = {
		{ text = "Yuka Screwspigot, de la part de sa parente Yorba" },
		{ text = "Ribbly Screwspigot" },
	},
	bonds = {
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "a mis la tête de Ribbly à prix" },
	},
})

Translate("frFR", "tinkee-steamboil", {
	title = "Tinkee Steamboil",
	subtitle = "Érudite des draconiens",
	found = "Corniche des flammes",
	hint = [=[Parlez à l'inventrice de la Corniche des flammes qui étudie les draconiens des Steppes.]=],
	allegiance = "Un protecteur caché",
	sections = {
		{
			title = "Résumé",
			text = [=[Tinkee Steamboil est une inventrice qui a passé des semaines à étudier les draconiens des Steppes depuis la {link:flame-crest}Corniche des flammes{/link}. Ses appareils capturent l'essence des dragonnets et gèlent les œufs de dragons noirs. Elle rêve de faire l'envie des érudits des dragons du monde entier. Elle sert aussi un protecteur qu'elle refuse de nommer, et elle prévient qu'il ne fait pas bon le décevoir.]=],
		},
		{
			title = "Importance",
			text = [=[Le travail de Tinkee devait livrer les œufs du vol noir à des mains dangereuses. S'il ne le fit pas, ce ne fut pas de son fait.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle construisit le Draco-Incarcinatrix 900 pour extraire l'essence des dragonnets.
• Elle chercha des pièces auprès de {link:felnok-steelspring}Felnok Steelspring{/link} à {link:everlook}Long-guet{/link} pour geler des œufs de dragon.
• Elle envoya des chercheurs à la couveuse du Pic {link:blackrock-mountain}Blackrock{/link} pour y prendre des œufs.]=],
		},
	},
	chapters = {
		{
			title = "Les œufs du maître",
			hint = "Portez les œufs gelés là où l'ordonne le maître de Tinkee.",
			text = [=[Un message arriva, qu'on disait venir de son maître, Vectus. Il était signé par un homme dont elle n'avait jamais entendu parler : {link:leonid-barthalomew}Leonid Barthalomew{/link}, à la {link:light-s-hope-chapel}Chapelle de l'Espoir de Lumière{/link}. Tinkee fut blessée que son maître confie les œufs à un autre, mais elle les envoya. Leonid n'était pas un serviteur de Vectus. C'était un chevalier de l'{link:argent-dawn}Aube d'argent{/link}, et il l'avait dupée, afin que les œufs n'atteignent jamais la puissance qu'elle avait servie.]=],
		},
	},
	mentions = {
		{ text = "Essence de dragonnet" },
		{ text = "{link:felnok-steelspring}Felnok Steelspring{/link}" },
		{ text = "Retour auprès de Tinkee" },
		{ text = "Tinkee Steamboil" },
		{ text = "Congélation d'œufs" },
		{ text = "Collecte d'œufs" },
		{ text = "{link:leonid-barthalomew}Leonid Barthalomew{/link}" },
	},
	bonds = {
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "l'a dupée" },
		{ id = "felnok-steelspring", name = "Felnok Steelspring", note = "son collègue" },
	},
})

Translate("frFR", "kibler", {
	title = "Kibler",
	subtitle = "Marchand d'animaux exotiques",
	found = "La Corniche des flammes, parmi ses cages",
	hint = [=[Trouvez le marchand d'animaux parmi les cages de la Corniche des flammes.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
