		},
	},
	mentions = {
		{ text = "Mor'zul Bloodbringer" },
		{ text = "Rage du sang" },
		{ text = "Wildeyes" },
		{ text = "Le destrier de l'effroi de Xoroth" },
	},
	bonds = {
		{ id = "gorzeeki-wildeyes", name = "Gorzeeki Wildeyes", note = "son serviteur" },
	},
})

